import React, { useState, useEffect } from 'react';
import api from '../api';

function CalendarView() {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [calendarData, setCalendarData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [selectedDay, setSelectedDay] = useState(null);
  const [dayDetails, setDayDetails] = useState(null);

  useEffect(() => {
    loadCalendarData();
  }, [currentDate]);

  const loadCalendarData = async () => {
    setLoading(true);
    try {
      const year = currentDate.getFullYear();
      const month = currentDate.getMonth() + 1;
      const data = await api.getCalendarData(year, month);
      setCalendarData(data);
    } catch (error) {
      console.error('Error loading calendar:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleDayClick = async (dateStr) => {
    try {
      const details = await api.getDayDetails(dateStr);
      setSelectedDay(dateStr);
      setDayDetails(details);
    } catch (error) {
      console.error('Error loading day details:', error);
    }
  };

  const getColor = (percentage) => {
    if (percentage >= 90) return 'green';
    if (percentage >= 50) return 'yellow';
    if (percentage > 0) return 'red';
    return 'gray';
  };

  const getDaysInMonth = () => {
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDay = new Date(year, month, 1);
    const lastDay = new Date(year, month + 1, 0);

    const days = [];
    const startingDayOfWeek = firstDay.getDay();
    const daysInMonth = lastDay.getDate();

    // Previous month days
    const prevMonth = new Date(year, month, 0);
    const daysInPrevMonth = prevMonth.getDate();
    const startDay = startingDayOfWeek === 0 ? 6 : startingDayOfWeek - 1;

    for (let i = startDay - 1; i >= 0; i--) {
      const day = daysInPrevMonth - i;
      const date = new Date(year, month - 1, day);
      days.push({ date, isCurrentMonth: false });
    }

    // Current month days
    for (let day = 1; day <= daysInMonth; day++) {
      const date = new Date(year, month, day);
      days.push({ date, isCurrentMonth: true });
    }

    // Next month days
    const remainingDays = 42 - days.length; // 6 weeks
    for (let day = 1; day <= remainingDays; day++) {
      const date = new Date(year, month + 1, day);
      days.push({ date, isCurrentMonth: false });
    }

    return days;
  };

  const getWeekStart = (date) => {
    const d = new Date(date);
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1);
    d.setDate(diff);
    return d.toISOString().split('T')[0];
  };

  const nextMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
  };

  const prevMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  };

  const today = new Date().toISOString().split('T')[0];

  if (loading) {
    return <div className="loading">Loading calendar...</div>;
  }

  const days = getDaysInMonth();

  return (
    <div className="main-content">
      <div className="page-header">
        <h1>Calendar View</h1>
        <p>Track team performance and completion rates</p>
      </div>

      <div className="calendar-container">
        <div className="calendar-header">
          <div className="calendar-nav">
            <button onClick={prevMonth}>← Previous</button>
            <span className="calendar-title">
              {currentDate.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}
            </span>
            <button onClick={nextMonth}>Next →</button>
          </div>
        </div>

        <div className="calendar-grid">
          {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(day => (
            <div key={day} className="calendar-day-header">{day}</div>
          ))}

          {days.map((dayObj, index) => {
            const dateStr = dayObj.date.toISOString().split('T')[0];
            const dayData = calendarData?.daily?.[dateStr] || { percentage: 0 };
            const weekStart = getWeekStart(dayObj.date);
            const weekData = calendarData?.weekly?.[weekStart] || { percentage: 0 };
            const isToday = dateStr === today;
            const isPast = new Date(dateStr) < new Date(today);

            return (
              <div
                key={index}
                className={`calendar-day ${!dayObj.isCurrentMonth ? 'other-month' : ''} ${isToday ? 'today' : ''}`}
                onClick={() => dayObj.isCurrentMonth && isPast && handleDayClick(dateStr)}
                style={{ cursor: dayObj.isCurrentMonth && isPast ? 'pointer' : 'default' }}
              >
                {dayObj.isCurrentMonth && isPast && (
                  <div className={`weekly-indicator ${getColor(weekData.percentage)}`} />
                )}
                <div className="day-number">{dayObj.date.getDate()}</div>
                {dayObj.isCurrentMonth && isPast && (
                  <>
                    <div className="day-completion">
                      {dayData.percentage}% complete
                    </div>
                    <div className={`completion-bar ${getColor(dayData.percentage)}`} />
                  </>
                )}
              </div>
            );
          })}
        </div>

        <div className="calendar-legend">
          <div className="legend-item">
            <div className="legend-color green"></div>
            <span>90%+ Complete</span>
          </div>
          <div className="legend-item">
            <div className="legend-color yellow"></div>
            <span>50-89% Complete</span>
          </div>
          <div className="legend-item">
            <div className="legend-color red"></div>
            <span>Below 50%</span>
          </div>
        </div>
      </div>

      {selectedDay && dayDetails && (
        <div className="modal-overlay" onClick={() => setSelectedDay(null)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Tasks for {new Date(selectedDay).toLocaleDateString()}</h2>
              <button className="modal-close" onClick={() => setSelectedDay(null)}>×</button>
            </div>

            {['daily', 'weekly', 'monthly'].map(frequency => (
              <div key={frequency} style={{ marginBottom: '30px' }}>
                <h3 style={{ marginBottom: '15px', textTransform: 'capitalize' }}>
                  {frequency} Tasks
                </h3>
                {dayDetails[frequency].length === 0 ? (
                  <p style={{ color: '#7f8c8d' }}>No {frequency} tasks</p>
                ) : (
                  dayDetails[frequency].map(task => (
                    <div key={task.id} style={{ 
                      border: '1px solid #e0e0e0', 
                      borderRadius: '6px', 
                      padding: '15px', 
                      marginBottom: '15px' 
                    }}>
                      <h4>{task.title}</h4>
                      {task.description && <p style={{ color: '#7f8c8d', fontSize: '14px' }}>{task.description}</p>}

                      <div style={{ marginTop: '10px' }}>
                        <strong>Completed by:</strong>
                        {task.completions && task.completions.length > 0 ? (
                          <ul style={{ marginTop: '5px' }}>
                            {task.completions.map(comp => (
                              <li key={comp.id}>
                                {comp.user_name} - {new Date(comp.completed_at).toLocaleString()}
                              </li>
                            ))}
                          </ul>
                        ) : (
                          <p style={{ color: '#e74c3c' }}>Not completed by anyone</p>
                        )}
                      </div>

                      {task.comments && task.comments.length > 0 && (
                        <div style={{ marginTop: '10px' }}>
                          <strong>Comments:</strong>
                          {task.comments.map(comment => (
                            <div key={comment.id} style={{ 
                              background: '#f8f9fa', 
                              padding: '8px', 
                              marginTop: '5px', 
                              borderRadius: '4px' 
                            }}>
                              <div style={{ fontSize: '12px', color: '#7f8c8d' }}>
                                {comment.user_name} - {new Date(comment.created_at).toLocaleString()}
                              </div>
                              <div>{comment.comment}</div>
                            </div>
                          ))}
                        </div>
                      )}

                      {task.files && task.files.length > 0 && (
                        <div style={{ marginTop: '10px' }}>
                          <strong>Files:</strong>
                          {task.files.map(file => (
                            <div key={file.id} style={{ marginTop: '5px' }}>
                              <a href={`/uploads/${file.filename}`} target="_blank" rel="noopener noreferrer">
                                📄 {file.original_name}
                              </a>
                              <span style={{ fontSize: '12px', color: '#7f8c8d', marginLeft: '10px' }}>
                                by {file.user_name}
                              </span>
                            </div>
                          ))}
                        </div>
                      )}
                    </div>
                  ))
                )}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

export default CalendarView;
